// Central configuration. Every downstream node reads $('Config').first().json.
const tz = 'America/Los_Angeles';
const now = new Date();
const run_date = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
let env = {};
try { env = { lm: $env.LMSTUDIO_URL, qd: $env.QDRANT_URL, dw: $env.DISCORD_WEBHOOK_URL, or: $env.OPENROUTER_API_KEY, gq: $env.GROQ_API_KEY, mu: $env.MISP_URL, mk: $env.MISP_API_KEY }; } catch (e) { /* env access blocked -> defaults below */ }
return [{ json: {
  run_date,
  run_started: now.toISOString(),
  timezone: tz,
  lookback_hours: 36,
  lmstudio_url: String(env.lm || 'http://localhost:11434/v1').replace(/\/$/, ''),
  qdrant_url: String(env.qd || 'http://qdrant:6333').replace(/\/$/, ''),
  // MISP as the story ledger (2026-09-12): one event per story, later days append attributes to the same event.
  // Key via $env (MISP_API_KEY, the OpenRouter precedent: sequencing create/append/read-back needs code). Empty = skipped.
  misp_url: String(env.mu || 'https://misp.example.com').replace(/\/$/, ''),
  misp_enabled: !!(env.mk && String(env.mk).trim()),
  misp_distribution: 0,              // "Your organisation only"
  misp_tags: ['tlp:clear', 'cyberintel:source="daily-digest"'],
  misp_to_ids_verdicts: ['malicious', 'suspicious'],
  chat_model: 'google/gemma-4-e2b',
  // Synthesis providers. PRIMARY: OpenRouter free models — the whole ":free" catalog is fetched live at run start
  // and ranked (preferred list first, then structured-output support, context, size). Per-model failures bench that
  // model for the run; an account-level limit (50 req/day without credits) benches OpenRouter for the run.
  // FAILOVER: LM Studio (bare 500s while (re)loading the model -> retry with backoff).
  openrouter_enabled: true,
  openrouter_has_key: !!(env.or && String(env.or).trim()),
  openrouter_min_context: 32000,
  openrouter_delay_ms: 600,          // stay well under the 20 req/min free-tier ceiling
  openrouter_cooldown_ms: 90000,     // a failing model sits out 90 s, doubling per strike (404/400 = out for the run)
  openrouter_timeout_ms: 90000,      // was 180 s; hanging free models were the main cost per story (2026-09-14)
  openrouter_preferred: ['nvidia/nemotron-3-super-120b-a12b:free', 'google/gemma-4-31b-it:free', 'dots-studio/dots-3-note-preview:free', 'minimax/minimax-m2.7:free', 'google/gemma-4-26b-a4b-it:free'],  // glm-5.2:free went paid-only 2026-09-06
  // Groq free tier (per-model tokens-per-day limits): second tier, absorbs what OpenRouter's 50/day cannot.
  groq_enabled: true,
  groq_has_key: !!(env.gq && String(env.gq).trim()),
  groq_min_context: 32000,
  groq_delay_ms: 2100,               // 30 req/min per model on the free tier
  groq_cooldown_ms: 90000,
  groq_timeout_ms: 120000,
  groq_preferred: ['openai/gpt-oss-120b', 'llama-3.3-70b-versatile', 'moonshotai/kimi-k2-instruct', 'qwen/qwen3-32b', 'openai/gpt-oss-20b', 'meta-llama/llama-4-maverick-17b-128e-instruct', 'meta-llama/llama-4-scout-17b-16e-instruct', 'llama-3.1-8b-instant'],
  provider_order: ['openrouter', 'groq', 'lmstudio'],   // per story, first provider that answers wins
  // Run-level time budget for synthesis (2026-09-14: 37 stories × ~3.5 min of hosted retries outlived the 90-min task
  // timeout and the day's digest never posted). Each story gets an equal share of what is left; a story that overruns
  // its share moves to the next provider, and once the budget is gone the rest go straight to LM Studio (one try).
  synth_budget_ms: 45 * 60 * 1000,
  synth_story_min_ms: 60 * 1000,
  lmstudio_tries: 3,
  lmstudio_backoff_ms: 8000,
  // Embeddings (LM Studio only — no free cloud embedding model exists). Switched 2026-09-11 from nomic-embed-text-v1.5
  // (768-d, 'search_document: ' prefix) to Qwen3-Embedding-4B (2560-d, documents take no prefix); the collection name
  // carries the model generation because Qdrant vector sizes are fixed per collection.
  embed_model: 'text-embedding-qwen3-embedding-4b',
  embed_dim: 2560,
  embed_prefix: '',
  collection: 'cyberintel_articles_v2',
  similarity_threshold: 0.78,        // join two articles when they ALSO share a CVE or >=2 distinctive title tokens
  similarity_threshold_hard: 0.92,   // join on vectors alone (near-identical text)
  prior_similarity_threshold: 0.85,  // link a story to something digested on an earlier day
  // Cross-encoder judge (Qwen3-Reranker-4B in LM Studio, added 2026-09-11): decides pairs the thresholds cannot —
  // cosine in [rerank_band_low, hard) without lexical evidence — and confirms prior-story candidates. Off = old behaviour.
  reranker_enabled: true,
  reranker_model: 'qwen3-reranker-4b',
  rerank_band_low: 0.70,
  rerank_max_pairs: 40,
  rerank_prior_links: true,
  max_article_chars: 9000,
  max_cluster_chars: 36000,          // ~10k tokens per story; keep well inside the model's loaded context
  max_output_tokens: 6000,           // gemma-4 spends hidden reasoning tokens; 2000 truncated a small test
  max_cves_to_enrich: 60,            // NVD is 5 req / 30 s without a key
  max_iocs_to_enrich: 200,           // VirusTotal free tier: 4/min, 500/day -> 200 lookups ~ 52 min worst case (severity-ordered)
  output_dir: '/data/intel/output',
  attack_map_path: '/data/intel/data/attack-techniques.json',
