// Rank OpenRouter's live ":free" catalogue for synthesis. Preferred (verified) models first, then models that
// advertise structured outputs, then by context and size. Falls back to the preferred list if the catalogue fetch failed.
const cfg = $('Config').first().json;
const pref = cfg.openrouter_preferred || [];
const minCtx = cfg.openrouter_min_context || 32000;
const body = ($json && $json.body !== undefined) ? $json.body : $json;
const catalogue = body && Array.isArray(body.data) ? body.data : null;
if (!catalogue) {
  return [{ json: { fetched: false, count: pref.length, models: pref.map(id => ({ id, structured: true, strict: true, context: 0, score: 0 })), note: 'OpenRouter catalogue unavailable: using preferred list only' } }];
}
const models = catalogue.filter(m => /:free$/.test(m.id || '')).map(m => {
  const sp = m.supported_parameters || [];
  const strict = sp.includes('structured_outputs'), rf = sp.includes('response_format');
  const ctx = Number(m.context_length) || 0;
  const maxOut = Number(m.top_provider && m.top_provider.max_completion_tokens) || 0;
  const sizeM = String(m.id).match(/(\d+(?:\.\d+)?)b\b/i); const sizeB = sizeM ? parseFloat(sizeM[1]) : 0;   // "2.6b" is 2.6, not 6
  const pi = pref.indexOf(m.id);
  let score = 0;
  if (pi >= 0) score += 1000 - pi * 10;
  if (strict) score += 300; else if (rf) score += 150;
  if (ctx >= 100000) score += 50; else if (ctx >= minCtx) score += 20;
  if (maxOut >= 8000) score += 20;
  score += Math.min(sizeB, 400) / 10;
  if (/safety|guard|moderation|code|coder|vision|embed|rerank/i.test(m.id)) score -= 400;   // classifiers / code / vision models: always last
  if (sizeB && sizeB < 4) score -= 100;                                                    // sub-4B models summarise poorly
  return { id: m.id, name: m.name, context: ctx, structured: strict || rf, strict, max_output: maxOut, score };
}).filter(m => m.context >= minCtx).sort((a, b) => b.score - a.score);
return [{ json: { fetched: true, count: models.length, total_free: catalogue.filter(m => /:free$/.test(m.id || '')).length, models } }];

// Rank Groq's model list for synthesis: preferred (chat-capable, known good) first, then context/size; exclude
// audio, guard, compound, embedding and reasoning-distill models. Falls back to the preferred list on fetch failure.
const cfg = $('Config').first().json;
const pref = cfg.groq_preferred || [];
const minCtx = cfg.groq_min_context || 32000;
const body = ($json && $json.body !== undefined) ? $json.body : $json;
const catalogue = body && Array.isArray(body.data) ? body.data : null;
if (!catalogue) {
  return [{ json: { fetched: false, count: pref.length, models: pref.map(id => ({ id, strict: true, structured: true, context: 0, score: 0 })), note: 'Groq catalogue unavailable: using preferred list only' } }];
}
const EXCL = /whisper|tts|guard|compound|embed|moderation|safeguard|orpheus|playai|allam|vision-preview/i;
const models = catalogue.filter(m => m.active !== false && !EXCL.test(m.id || '')).map(m => {
  const ctx = Number(m.context_window) || 0;
  const sizeM = String(m.id).match(/(\d+(?:\.\d+)?)b\b/i); const sizeB = sizeM ? parseFloat(sizeM[1]) : 0;
  const pi = pref.indexOf(m.id);
  let score = 0;
  if (pi >= 0) score += 1000 - pi * 10;
  if (ctx >= 100000) score += 50; else if (ctx >= minCtx) score += 20;
  score += Math.min(sizeB, 400) / 10;
  if (/instant|mini|small/i.test(m.id) && sizeB && sizeB < 10) score -= 30;
  if (/distill|r1|reasoning/i.test(m.id)) score -= 60;
  return { id: m.id, owned_by: m.owned_by, context: ctx, strict: true, structured: true, score };
}).filter(m => m.context >= minCtx).sort((a, b) => b.score - a.score);
return [{ json: { fetched: true, count: models.length, total: catalogue.length, models } }];

