  .replace(/&quot;/g, '"').replace(/&#0?39;|&#x27;|&apos;/g, "'")
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n))
  .replace(/\s+/g, ' ').trim();
// No `URL` global in the n8n task-runner sandbox — regex only.
const TRACKING = /^(utm_[a-z]+|ref|source|mc_cid|mc_eid|fbclid|gclid)=/i;
const canon = u => {
  let s = String(u || '').trim().replace(/#.*$/, '');
  const m = s.match(/^([a-z][a-z0-9+.-]*:\/\/)([^/?#]+)(.*)$/i);
  if (!m) return s;
  let rest = m[3];
  const qi = rest.indexOf('?');
  if (qi >= 0) {
    const kept = rest.slice(qi + 1).split('&').filter(p => p && !TRACKING.test(p));
    rest = rest.slice(0, qi) + (kept.length ? '?' + kept.join('&') : '');
