const hostOf = u => ((String(u).match(/^[a-z][a-z0-9+.-]*:\/\/([^/?#:]+)/i) || [])[1] || '').toLowerCase().replace(/^www\./, '');
const seenUrl = new Set(), seenTitle = new Set(), out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.error || !j.link) continue;
  const url = canon(j.link);
  if (seenUrl.has(url)) continue;
  const pub = new Date(j.isoDate || j.pubDate || j.published || j.updated || 0);
  if (isNaN(pub.getTime()) || pub.getTime() < cutoff) continue;
  const title = strip(j.title);
  const tkey = title.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (tkey && seenTitle.has(tkey)) continue;
  const host = hostOf(url);
  const hit = Object.entries(HOST_MAP).find(([k]) => host === k || host.endsWith('.' + k));
  const source = hit ? hit[1] : host;
  const rssHtml = j['content:encoded'] || j.content || j.summary || j.description || j.contentSnippet || '';
  const categories = Array.isArray(j.categories) ? j.categories.map(c => typeof c === 'string' ? c : (c && (c._ || c.name)) || '').filter(Boolean) : [];
  seenUrl.add(url); if (tkey) seenTitle.add(tkey);
  out.push({ json: { url, title, source, published: pub.toISOString(), rss_text: strip(rssHtml).slice(0, cfg.max_article_chars), categories } });
}
out.sort((a, b) => b.json.published.localeCompare(a.json.published));
return out;

