return articles.filter(a => !found.has(a.id)).map(a => ({ json: a }));

const meta = $('Filter New').item.json;
const cfg = $('Config').first().json;
// HTTP Request (fullResponse + text) emits { data, headers, statusCode, statusMessage }; the page is in `data`.
const status = Number($json.statusCode || 0);
const html = (typeof $json.data === 'string') ? $json.data : ((typeof $json.body === 'string') ? $json.body : '');

const decode = s => String(s)
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#0?39;|&#x27;|&apos;/g, "'")
  .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(+n))
  .replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&[a-z]+;/gi, ' ');
const textOf = frag => decode(String(frag)
  .replace(/<(script|style|noscript|svg|iframe|form|nav|footer|header|aside|figure|button)\b[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<!--[\s\S]*?-->/g, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|h[1-6]|tr|blockquote|pre|section)>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t ]+/g, ' ').replace(/\s*\n\s*/g, '\n').trim();

let text = '';
if (status >= 200 && status < 300 && html) {
  const pick = re => { const m = html.match(re); return m ? m[1] : null; };
  for (const c of [pick(/<article\b[^>]*>([\s\S]*?)<\/article>/i), pick(/<main\b[^>]*>([\s\S]*?)<\/main>/i), pick(/<body\b[^>]*>([\s\S]*?)<\/body>/i), html]) {
    if (!c) continue; const t = textOf(c); if (t.length > 800) { text = t; break; }
  }
}
// Cut trailing page chrome ("Related Articles", share prompts, trending widgets) so their CVEs/IOCs
