const CHROME = /\n\s*(Related Articles?:?|Related:|Related Stories|Related Posts|Trending|Popular Stories|Read more:?|Read Next|You may also like|Recommended( for you)?|More from|Found this article interesting\?|Share (this|on)|Follow us|Sponsored|Advertisement|Tags:|Comments?( \(\d+\))?|Post a Comment|Subscribe)\b/i;
if (text) {
  const m = text.match(CHROME);
  if (m && m.index > text.length / 3) text = text.slice(0, m.index).trim();
}
let text_source = text ? 'full' : 'rss';
if (!text || text.length < 400) { text = meta.rss_text || text; text_source = 'rss'; }
text = String(text).slice(0, cfg.max_article_chars);

// ---- deterministic extraction (the LLM is never trusted for identifiers) ----
