    return add({ ...base('indicator', `ioc:${t}:${c.value}`), name: `${t}: ${c.value}`, description: c.comment, pattern: PAT[t](c.value), pattern_type: 'stix', pattern_version: '2.1', valid_from: c.first_seen + 'T00:00:00.000Z',
      indicator_types: [verdict === 'clean' ? 'benign' : 'malicious-activity'], labels: ['cumulative-from-misp', 'verdict-' + verdict], x_ioc_verdict: verdict, x_first_seen_digest: c.first_seen, x_misp_event_id: mp.event_id, external_references: [{ source_name: 'MISP', url: mp.event_url }] }); }) : [];
