const bundle = { type: 'bundle', id: 'bundle--' + uuidFrom('bundle:' + cfg.run_date + ':' + nowIso), objects: S };

// ------------------------------------------------------------------ Discord (summary embed + digest attached, then the STIX bundle)
const DCOL = { critical: 0xE01E5A, high: 0xF2A100, medium: 0x2EB67D, low: 0x3B82F6, info: 0x6B7280 };
const topSev = stories.length ? stories[0].brief.severity : 'info';
const dPrio = prio.slice(0, 15).map(s => {
  const bits = s.brief.cves.filter(v => hot(v.id)).map(v => `${v.id} (${cveTags(v.id).replace(/\*\*/g, '')})`);
  const mc = maliciousCount(s); if (mc) bits.push(`${mc} malicious IOC${mc > 1 ? 's' : ''}`);
  return `**[${s.brief.severity.toUpperCase()}]** §${s.num} ${s.brief.headline}${bits.length ? ' — ' + bits.join(', ') : ''}`;
});
let dDesc = dPrio.length ? dPrio.join('\n') : '_No priority items today — see the attached digest._';
if (prio.length > 15) dDesc += `\n_… ${prio.length - 15} more in the attached digest_`;
if (dDesc.length > 4000) dDesc = dDesc.slice(0, 3990) + '…';
const kevCount = allCves.filter(id => e(id).kev).length;
const byTypeCounts = S.reduce((m, o) => (m[o.type] = (m[o.type] || 0) + 1, m), {});
const discordDigest = { username: 'CyberIntel Digest', allowed_mentions: { parse: [] }, embeds: [{
  title: `Cyber Intel Digest — ${cfg.run_date}`, description: dDesc, color: DCOL[topSev] || DCOL.info, timestamp: nowIso,
  fields: [
    { name: 'Stories', value: String(stories.length), inline: true },
    { name: 'CVEs', value: `${allCves.length}${kevCount ? ` (${kevCount} KEV)` : ''}`, inline: true },
    { name: 'IOCs', value: `${iocRows.length}${iocStats ? ` (${iocStats.malicious} malicious)` : ''}`, inline: true },
    { name: 'ATT&CK', value: String(tidList.length), inline: true },
