let stixLine = `📎 STIX 2.1 bundle — ${cfg.run_date} — ${S.length} objects: ` + Object.entries(byTypeCounts).map(([k, v]) => `${v} ${k}`).join(', ');
if (stixLine.length > 1900) stixLine = stixLine.slice(0, 1890) + '…';
const discordStix = { username: 'CyberIntel Digest', allowed_mentions: { parse: [] }, content: stixLine };

// ------------------------------------------------------------------ data + files
const data = { run_date: cfg.run_date, generated: nowIso,
  stats: { feeds: cfg.feeds.length, articles_in_window: windowCount, new_articles: newCount, stories: stories.length, cves: allCves.length, iocs: iocRows.length, iocs_malicious: iocStats ? iocStats.malicious : null, techniques: tidList.length, stix_objects: S.length },
  config: { ...cfg, feeds: undefined }, stories: stories.map(s => ({ ...s, articles: s.articles.map(a => { const { text, ...r } = a; return r; }) })), enriched, ioc_intel: { stats: iocStats, iocs: iocIntel }, notes };
