  { json: { fileName: `${cfg.run_date}-digest.md`, content: md, discord_post: true, discord: discordDigest } },
  { json: { fileName: `${cfg.run_date}-stix.json`, content: JSON.stringify(bundle, null, 2), discord_post: true, discord: discordStix } },
  { json: { fileName: `${cfg.run_date}-data.json`, content: JSON.stringify(data, null, 2), discord_post: false } },
