// Articles that could not be embedded get a deterministic one-hot placeholder (Qdrant rejects zero vectors under cosine)
// and payload embedded:false, so dedup-by-id works while prior-story search skips them (see Search Prior Body).
const DIM = Number(cfg.embed_dim) || 768;
