  payload: { url: a.url, title: a.title, source: a.source, published: a.published, published_ts: Math.floor(new Date(a.published).getTime() / 1000), digest_date: cfg.run_date, cluster_id: clusterOf[a.id] || null, cves: a.cves || [], embedded: Array.isArray(a.vector), ...mispOf(clusterOf[a.id]) },
